{
  "implementation": "def solve(case):
    lines = case.get('lines', [])
    if not lines:
        return {'valid': False, 'error_line': None, 'trajectory': []}
    trajectory = []
    valid = True
    error_line = None
    state = 'initial'
    allowed = {
        'initial': {'thought', 'final'},
        'after_thought': {'action', 'final'},
        'after_action': {'action_input', 'observation'},
        'after_action_input': {'observation'},
        'after_observation': {'thought', 'final'},
        'done': set()
    }
    for line_num, line in enumerate(lines, start=1):
        line = line.strip()
        if not line:
            error_line = line_num
            valid = False
            break
        colon_pos = line.find(':')
        if colon_pos == -1:
            type_str = None
            content = line
        else:
            type_str = line[:colon_pos].strip().lower()
            content = line[colon_pos+1:].strip()
        known_types = {'thought', 'action', 'action_input', 'observation', 'final'}
        if type_str not in known_types:
            error_line = line_num
            valid = False
            break
        if type_str not in allowed[state]:
            error_line = line_num
            valid = False
            break
        trajectory.append({'type': type_str, 'content': content})
        if type_str == 'thought':
            state = 'after_thought'
        elif type_str == 'action':
            state = 'after_action'
        elif type_str == 'action_input':
            state = 'after_action_input'
        elif type_str == 'observation':
            state = 'after_observation'
        elif type_str == 'final':
            state = 'done'
    else:
        if state != 'done':
            if trajectory:
                trajectory.pop()
            error_line = line_num if line_num else None
            valid = False
    return {'valid': valid, 'error_line': error_line, 'trajectory': trajectory}"
